return-response.set-body:
@{
        var code      = context.Request.Url.Query.GetValueOrDefault("code", "");
        var error     = context.Request.Url.Query.GetValueOrDefault("error", "");
        var errorDesc = context.Request.Url.Query.GetValueOrDefault("error_description", "");

        var style = "";

        if (!string.IsNullOrEmpty(error)) {
          return "
Consent Error" + style + ""
            + "Error"
            + "
Consent was not granted"
            + "
" + System.Net.WebUtility.HtmlEncode(error) + ""
            + "
" + System.Net.WebUtility.HtmlEncode(errorDesc) + ""
            + "";
        }

        if (string.IsNullOrEmpty(code)) {
          return "
Callback Error" + style + ""
            + "Error"
            + "
Unexpected callback"
            + "
The callback was called without a code or error parameter."
            + "";
        }

        return "
Consent Granted" + style + ""
          + "Success"
          + "
Consent granted ✔"
          + "
Azure DevOps access has been authorized. You can close this window."
          + "
Return to your MCP client and retry your request — "
          + "the on-behalf-of exchange will now succeed."
          + "";
      }
